WITH pkg AS (
  INSERT INTO public.knowledge_packages (organization_id, slug, domain, status, default_language)
  VALUES
    (NULL, 'pi-evm-spi-cpi', 'product_intelligence', 'published', 'en'),
    (NULL, 'pi-kpi-milestone-dimension', 'product_intelligence', 'published', 'en'),
    (NULL, 'pi-kpi-expression-rules', 'product_intelligence', 'published', 'en'),
